import type { FloatProps } from "./float.types";

import React, { forwardRef } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";

import { FloatClasses, StyledFloat } from "./float.styles";
import { FloatContext, useFloat } from "./hooks/use-float";

const FloatRoot = forwardRef(
  (
    {
      className,
      variant = "default",
      placement = "top-end",
      offSetY = 0,
      offSetX = 0,
      children,
      ...props
    }: FloatProps,
    ref: React.ForwardedRef<HTMLDivElement>,
  ) => {
    const theme = useTheme(),
      rootClasses = clsx(FloatClasses.root, className);

    return (
      <FloatContext.Provider value={{ placement }}>
        <StyledFloat
          ref={ref}
          className={rootClasses}
          currentTheme={theme}
          offSetX={offSetX}
          offSetY={offSetY}
          variant={variant}
          {...props}
        >
          {children}
        </StyledFloat>
      </FloatContext.Provider>
    );
  },
);
FloatRoot.displayName = "Float";

const FloatContent: React.FC<React.PropsWithChildren<{ className?: string }>> = ({
  className,
  children,
  ...props
}) => {
  const { placement } = useFloat();

  const contentProps = {
    className: clsx(FloatClasses.content, className),
    "data-placement": placement,
    ...props,
  };

  if (React.isValidElement(children)) {
    return React.cloneElement(children, contentProps);
  } else {
    throw new Error(
      "Float.Content must be used as a child of Float and must be a valid React element.",
    );
  }
};
FloatContent.displayName = "Float.Content";

const FloatAnchor: React.FC<React.PropsWithChildren<{ className?: string }>> = ({
  className,
  children,
  ...props
}) => {
  const contentProps = {
    className: clsx(FloatClasses.anchor, className),
    ...props,
  };

  if (React.isValidElement(children)) {
    return React.cloneElement(children, contentProps);
  } else {
    throw new Error(
      "Float.Anchor must be used as a child of Float and must be a valid React element.",
    );
  }
};
FloatAnchor.displayName = "Float.Anchor";

const Float = Object.assign(FloatRoot, {
  Content: FloatContent,
  Anchor: FloatAnchor,
});

export default Float;
